class Solution {
    public int maximumWealth(int[][] accounts) {
        int richest = 0;
        for (int[] customer : accounts) {
            int wealth = 0;
            for (int money : customer) {
                wealth += money;
            }
            richest = Math.max(richest, wealth);
        }
        return richest;
    }
}

class Solution {
    public int maximumWealth(int[][] accounts) {
        int[] wealth = new int[accounts.length];
        for (int customer = 0; customer < accounts.length; customer++) {
            for (int bank = 0; bank < accounts[customer].length; bank++) {
                wealth[customer] += accounts[customer][bank];
            }
        }

        int richest = wealth[0];
        for (int customer = 1; customer < wealth.length; customer++) {
            if (wealth[customer] > richest) {
                richest = wealth[customer];
            }
        }
        return richest;
    }
}

class Solution {
    public int maximumWealth(int[][] accounts) {
        int m = accounts.length;
        int n = accounts[0].length;
        int richest = 0;
        int rowSum = 0;

        for (int index = 0; index < m * n; index++) {
            int row = index / n;
            int column = index % n;
            rowSum += accounts[row][column];
            if (column == n - 1) {
                richest = Math.max(richest, rowSum);
                rowSum = 0;
            }
        }
        return richest;
    }
}

class Solution {
    public int maximumWealth(int[][] accounts) {
        return richestFrom(accounts, 0);
    }

    private int richestFrom(int[][] accounts, int customer) {
        if (customer == accounts.length) {
            return 0;
        }
        int current = rowWealth(accounts[customer], 0);
        int later = richestFrom(accounts, customer + 1);
        return Math.max(current, later);
    }

    private int rowWealth(int[] balances, int bank) {
        if (bank == balances.length) {
            return 0;
        }
        return balances[bank] + rowWealth(balances, bank + 1);
    }
}
